#include <bits/stdc++.h>
#define LOOP_START(i,a,b) for(int i=(a);i<=(b);i++)
#define LOOP_END(i,a,b) for(int i=(a);i>=(b);i--)
using namespace std;
const int MAXN=505;
int n,m,mod;
int modWrap(int x){
	if(x<0)return x+mod;
	if(x>=mod)return x-mod;
	return x;
}
void updateVal(int &x,int y){
	x=modWrap(x+y);
}
int fastExponentiation(int base,int exp){
	int res=1;
	while(exp){
		if(exp&1)res=1ll*res*base%mod;
		base=1ll*base*base%mod;
		exp>>=1;
	}
	return res;
}
int fact[MAXN*4],invFact[MAXN*4];
void precomputeFactorials(int n){
	fact[0]=1;
	LOOP_START(i,1,n)fact[i]=1ll*fact[i-1]*i%mod;
	invFact[n]=fastExponentiation(fact[n],mod-2);
	LOOP_END(i,n-1,0)invFact[i]=1ll*invFact[i+1]*(i+1)%mod;
}
int choose(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*fact[n]*invFact[n-m]%mod*invFact[m]%mod;
}
vector<int> polyF,gPoly;
int sumSeries(int x){
	return x*(x+1)/2;
}
vector<int> multiplyPoly(const vector<int> &A,const vector<int> &B){
	vector<int> C(A.size()+B.size()-1);
	LOOP_START(i,0,(int)A.size()-1)LOOP_START(j,0,(int)B.size()-1)updateVal(C[i+j],1ll*A[i]*B[j]%mod);
	return C;
}
int G(int n,int m){
	return choose(m+n-1,n-1);
}
int main(){
#ifdef pig
	freopen("1439D.in","r",stdin);
	freopen("1439D.out","w",stdout);
#endif
	cin>>m>>n>>mod;
	precomputeFactorials(m<<1);
	polyF.resize(n+1);gPoly.resize(n+1);
	polyF[0]=1;
	LOOP_START(i,1,n){
		LOOP_START(j,0,i-1)updateVal(polyF[i],1ll*polyF[j]*polyF[i-1-j]%mod*choose(i-1,j)%mod);
		polyF[i]=1ll*polyF[i]*(i+1)%mod;
	}
	LOOP_START(i,1,n){
		LOOP_START(j,0,i-1)updateVal(gPoly[i],(2ll*polyF[j]*gPoly[i-1-j]%mod*choose(i-1,j)%mod*(i+1)%mod+1ll*choose(i-1,j)*(sumSeries(j)+sumSeries(i-1-j))%mod*polyF[j]%mod*polyF[i-1-j]%mod)%mod);
	}
	polyF[0]=0;
	LOOP_START(i,0,n)gPoly[i]=1ll*gPoly[i]*invFact[i]%mod;
	LOOP_START(i,0,n)polyF[i]=1ll*polyF[i]*invFact[i]%mod;
	int totalAns=0;
	LOOP_START(i,1,m-n+1){
		updateVal(totalAns,1ll*gPoly[n]*G(i+1,m-n-i+1)%mod*fact[n]%mod*i%mod);
		gPoly=multiplyPoly(gPoly,polyF);gPoly.resize(n+1);
	}
	cout<<totalAns;
	return 0;
}
